  // QR Feedback States
  const [detectedBarcodeBounds, setDetectedBarcodeBounds] = useState<{x: number, y: number, width: number, height: number} | null>(null);
  const [isCodeDetectedTransient, setIsCodeDetectedTransient] = useState(false);

