export const AnalysisDisplay: React.FC<AnalysisDisplayProps> = ({ result, isLoading, error, onViewIngredient }) => {
  const { playClick, playSuccess, announce } = useAccessibility();
  const [isSearching, setIsSearching] = useState(false);
  const [searchResult, setSearchResult] = useState<{ text: string; groundingMetadata: any } | null>(null);
  const [searchError, setSearchError] = useState<string | null>(null);
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const [webImage, setWebImage] = useState<string | null>(null);
  const [imgError, setImgError] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
      if (result?.productName) {
          setWebImage(null);
          setImgError(false);
          findProductImage(result.productName).then(url => {
              if (url) setWebImage(url);
          });
      }
      return () => {
        stopAudio();
      };
  }, [result?.productName]);

  const stopAudio = () => {
    if (audioSourceRef.current) {
        audioSourceRef.current.stop();
        audioSourceRef.current = null;
    }
    setIsSpeaking(false);
  };

  const handleWebSearch = async () => {
      if (!result?.productName) return;
      playClick();
      setIsSearching(true);
      setSearchResult(null);
      setSearchError(null);
      announce("Searching web for details");
      try {
          const data = await searchProductWeb(result.productName);
          setSearchResult(data);
          playSuccess();
          announce("Web search results loaded");
      } catch (e) {
          setSearchError("Failed to search the web.");
      } finally {
          setIsSearching(false);
      }
  };

  const handleSpeakAnalysis = async () => {
    if (!result || isSpeaking) {
        if (isSpeaking) stopAudio();
        return;
    }

    playClick();
    setIsSpeaking(true);
    announce("Generating speech for analysis...");

    try {
        const textToSpeak = `
            Analysis for ${result.productName}. 
            Summary: ${result.skinAnalysis.summary}. 
            Positive effects include: ${result.skinAnalysis.positiveEffects.join(', ')}. 
            Safety check: ${result.recallInfo?.hasRecall ? result.recallInfo.details : 'No recent recalls found.'}
        `;

        const base64Audio = await generateSpeech(textToSpeak);

        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }

        const ctx = audioContextRef.current;
        if (ctx.state === 'suspended') await ctx.resume();

        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => {
            setIsSpeaking(false);
            audioSourceRef.current = null;
        };

        audioSourceRef.current = source;
        source.start();
        announce("Reading analysis results");
    } catch (err) {
        console.error("Speech generation failed", err);
        setIsSpeaking(false);
        announce("Speech generation failed");
    }
  };

  const handleShareClick = () => {
    playClick();
    setIsShareModalOpen(true);
  };

  if (isLoading) {
    return (
      <div role="status" className="flex flex-col items-center justify-center bg-white dark:bg-gray-800 p-8 rounded-2xl shadow-lg h-full min-h-[400px] transition-colors duration-200">
        <Spinner className="text-brand-green-dark dark:text-brand-green" />
        <p className="mt-4 text-brand-gray-dark dark:text-white font-semibold">Analyzing your product...</p>
        <p className="mt-2 text-sm text-brand-gray dark:text-gray-400">This may take a moment.</p>
      </div>
    );
  }

  if (error) {
    return (
      <div role="alert" className="flex flex-col items-center justify-center bg-red-50 dark:bg-red-900/20 p-8 rounded-2xl shadow-lg h-full min-h-[400px] transition-colors duration-200">
        <ExclamationTriangleIcon className="h-12 w-12 text-red-500" />
        <p className="mt-4 text-red-700 dark:text-red-400 font-bold text-lg">Analysis Failed</p>
        <p className="mt-2 text-sm text-red-600 dark:text-red-300 text-center">{error}</p>
      </div>
    );
  }

  if (!result) {
    return (
      <div className="flex flex-col items-center justify-center bg-white dark:bg-gray-800 p-8 rounded-2xl shadow-lg h-full min-h-[400px] text-center transition-colors duration-200">
        <LeafIcon className="h-16 w-16 text-gray-300 dark:text-gray-600" />
        <p className="mt-4 text-brand-gray-dark dark:text-white font-semibold">Your analysis will appear here.</p>
        <p className="mt-2 text-sm text-brand-gray dark:text-gray-400">Scan a product's QR code and click "Analyze" to begin.</p>
      </div>
    );
  }

  const shareData = {
    title: `Skincare Scanner: ${result.productName}`,
    text: `I just analyzed ${result.productName} with Skincare Scanner!\n\nSummary: ${result.skinAnalysis.summary}`,
    url: window.location.origin
  };

  return (
    <div className="space-y-6">
      <div className="bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-lg transition-colors duration-200 relative">

        <div className="absolute top-6 right-6 z-10 flex gap-2">
             <button
                onClick={handleSpeakAnalysis}
                className={`p-2 rounded-full transition-colors focus:outline-none focus:ring-2 focus:ring-brand-green ${
                    isSpeaking 
                    ? 'bg-brand-green text-white animate-pulse' 
                    : 'bg-gray-100 dark:bg-gray-700 text-brand-gray dark:text-gray-300 hover:text-brand-green hover:bg-brand-green/10'
                }`}
                title={isSpeaking ? "Stop Speaking" : "Listen to Analysis"}
                aria-label={isSpeaking ? "Stop Speaking" : "Listen to Analysis"}
             >
                 <AudioSparkIcon className="h-6 w-6" />
             </button>
             <button
                onClick={handleShareClick}
                className="p-2 rounded-full bg-gray-100 dark:bg-gray-700 text-brand-gray dark:text-gray-300 hover:text-brand-green hover:bg-brand-green/10 transition-colors focus:outline-none focus:ring-2 focus:ring-brand-green"
                title="Share Analysis"
                aria-label="Share Analysis"
             >
                 <ShareIcon className="h-6 w-6" />
             </button>
        </div>

        {webImage && !imgError && (
            <div className="flex justify-center mb-6 animate-fade-in">
                <div className="relative group">
                    <img 
                        src={webImage} 
                        alt={`Image of ${result.productName}`} 
                        className="h-40 w-40 object-contain rounded-xl bg-white border border-gray-100 dark:border-gray-700 shadow-sm"
                        onError={() => setImgError(true)}
                    />
                </div>
            </div>
        )}

        <h2 className="text-3xl font-bold text-brand-green-dark dark:text-brand-green text-center pr-24 pl-24 truncate">{result.productName}</h2>

        <div className="mt-4 flex flex-col items-center">
            {!searchResult && !isSearching && (
                <button 
                    onClick={handleWebSearch}
                    className="flex items-center text-sm font-medium text-blue-600 dark:text-blue-400 hover:underline focus:outline-none focus:ring-2 focus:ring-blue-500 rounded px-2"
                >
                    <MagnifyingGlassIcon className="w-4 h-4 mr-1" />
                    Search for latest reviews & safety info
                </button>
            )}

            {isSearching && <Spinner className="text-blue-500 w-5 h-5 mt-2" />}

            {searchError && <p role="alert" className="text-sm text-red-500 mt-2">{searchError}</p>}

            {searchResult && (
                <div className="mt-4 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-xl border border-blue-100 dark:border-blue-800 w-full text-left animate-fade-in">
                    <h4 className="font-bold text-blue-800 dark:text-blue-300 mb-2 flex items-center">
                        <MagnifyingGlassIcon className="w-4 h-4 mr-2" />
                        Web Search Insights
                    </h4>
                    <p className="text-sm text-gray-700 dark:text-gray-300 whitespace-pre-wrap leading-relaxed mb-3">
                        {searchResult.text}
                    </p>

                    {/* Display grounding chunks as links as required by Gemini API guidelines */}
                    {searchResult.groundingMetadata?.groundingChunks && (
                        <div className="pt-2 border-t border-blue-100 dark:border-blue-800">
                            <p className="text-xs font-semibold text-blue-600 dark:text-blue-400 mb-2">Sources:</p>
                            <ul className="space-y-1.5">
                                {searchResult.groundingMetadata.groundingChunks.map((chunk: any, i: number) => (
                                    chunk.web && (
                                        <li key={i}>
                                            <a 
                                                href={chunk.web.uri} 
                                                target="_blank" 
                                                rel="noopener noreferrer" 
                                                className="text-xs text-blue-600 dark:text-blue-400 hover:underline flex items-center gap-1.5"
                                            >
                                                <LinkIcon className="w-3 h-3 flex-shrink-0" />
                                                <span className="truncate">{chunk.web.title || chunk.web.uri}</span>
                                            </a>
                                        </li>
                                    )
                                ))}
                            </ul>
                        </div>
                    )}
                </div>
            )}
        </div>
      </div>

      {result.recallInfo && (
        <div role="region" aria-label="Recall Information" className={`p-5 rounded-xl shadow-md transition-all duration-300 border ${
            result.recallInfo.hasRecall 
            ? 'bg-red-100 dark:bg-red-900/30 border-red-500 dark:border-red-500 border-2 ring-4 ring-red-100 dark:ring-red-900/20' 
            : 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800'
        }`}>
            <div className="flex items-center mb-2">
                {result.recallInfo.hasRecall ? (
                    <div className="relative flex-shrink-0">
                         <ExclamationTriangleIcon className="h-8 w-8 text-red-600 dark:text-red-400 relative z-10" />
                    </div>
                ) : (
                    <CheckCircleIcon className="h-6 w-6 text-green-600 dark:text-green-400 flex-shrink-0" />
                )}
                <h3 className={`text-lg font-bold ml-4 ${result.recallInfo.hasRecall ? 'text-red-800 dark:text-red-200 text-xl uppercase tracking-wide' : 'text-green-800 dark:text-green-300'}`}>
                    {result.recallInfo.hasRecall ? '⚠️ Recall Alert Detected' : 'Safety Check: No Recalls'}
                </h3>
            </div>
            <div className={result.recallInfo.hasRecall ? "ml-12" : "ml-9"}>
                 <p className={`text-sm ${result.recallInfo.hasRecall ? 'text-red-900 dark:text-red-100 font-medium text-base' : 'text-green-700 dark:text-green-200'} leading-relaxed`}>
                    {result.recallInfo.details}
                </p>
            </div>
        </div>
      )}

      <InfoCard title="Personalized Skin Analysis" icon={<InformationCircleIcon className="h-6 w-6 text-blue-500" />}>
        <p className="text-brand-gray dark:text-gray-300 text-base mb-4">{result.skinAnalysis.summary}</p>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
                <h4 className="font-semibold text-green-700 dark:text-green-400 mb-2 flex items-center">
                    <CheckCircleIcon className="h-5 w-5 mr-2 text-green-500" />
                    Potential Positives
                </h4>
                <ul className="space-y-2 text-sm text-brand-gray-dark dark:text-gray-300">
                    {result.skinAnalysis.positiveEffects.map((effect, i) => (
                        <li key={i} className="flex items-start">
                            <CheckCircleIcon className="h-4 w-4 text-green-500 mr-2 mt-0.5 flex-shrink-0"/>
                            <span>{effect}</span>
                        </li>
                    ))}
                </ul>
            </div>
             <div>
                <h4 className="font-semibold text-red-700 dark:text-red-400 mb-2 flex items-center">
                    <ExclamationTriangleIcon className="h-5 w-5 mr-2 text-yellow-500"/>
                    Things to Watch
                </h4>
                <ul className="space-y-2 text-sm text-brand-gray-dark dark:text-gray-300">
                    {result.skinAnalysis.negativeEffects.map((effect, i) => (
                        <li key={i} className="flex items-start">
                            <ExclamationTriangleIcon className="h-4 w-4 text-yellow-500 mr-2 mt-0.5 flex-shrink-0"/>
                            <span>{effect}</span>
                        </li>
                    ))}
                </ul>
            </div>
        </div>
      </InfoCard>

      <InfoCard title="Key Ingredients" icon={<LeafIcon className="h-6 w-6 text-green-500" />}>
        <ul className="space-y-4">
          {result.ingredients.map((item, i) => (
            <li key={i} className="text-sm flex flex-col sm:flex-row sm:items-start gap-2 sm:gap-3 border-b border-gray-100 dark:border-gray-700 last:border-0 pb-3 last:pb-0">
               <div className="flex-shrink-0 pt-0.5">
                  <button 
                    onClick={() => onViewIngredient(item.name)} 
                    className="inline-flex items-center px-3 py-1 rounded-full text-xs font-bold bg-brand-green/10 text-brand-green-dark dark:text-brand-green-light border border-brand-green/20 hover:bg-brand-green hover:text-white dark:hover:text-white transition-all duration-200 shadow-sm group focus:outline-none focus:ring-2 focus:ring-brand-green"
                    title={`View details for ${item.name}`}
                    aria-label={`View details for ${item.name}`}
                  >
                     {item.name}
                     <InformationCircleIcon className="h-3.5 w-3.5 ml-1.5 opacity-70 group-hover:opacity-100"/>
                  </button>
              </div>
              <span className="text-brand-gray dark:text-gray-300 leading-relaxed flex-grow">{item.description}</span>
            </li>
          ))}
        </ul>
      </InfoCard>

      <InfoCard title="Nutritional Info" icon={<LeafIcon className="h-6 w-6 text-purple-500" />}>
         <ul className="space-y-3">
          {result.nutrients.map((item, i) => (
            <li key={i} className="text-sm">
              <span className="font-semibold text-brand-gray-dark dark:text-white">{item.name} ({item.amount}):</span>
              <span className="text-brand-gray dark:text-gray-400 ml-1">{item.description}</span>
            </li>
          ))}
        </ul>
      </InfoCard>

      <ShareModal 
        isOpen={isShareModalOpen} 
        onClose={() => setIsShareModalOpen(false)} 
        data={shareData} 
      />
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Chat } from "@google/genai";
import { UserProfile } from '../types';
import { createChatSession, generateSpeech, decode, decodeAudioData } from '../services/geminiService';
import { ChatBubbleLeftRightIcon } from './icons/ChatBubbleLeftRightIcon';
import { PaperAirplaneIcon } from './icons/PaperAirplaneIcon';
import { XMarkIcon } from './icons/XMarkIcon';
import { Spinner } from './Spinner';
import { useAccessibility } from '../contexts/AccessibilityContext';
import { SparklesIcon } from './icons/SparklesIcon';
import { AudioSparkIcon } from './icons/AudioSparkIcon';

interface ChatBotProps {
  userProfile: UserProfile;
}

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
}

export const ChatBot: React.FC<ChatBotProps> = ({ userProfile }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { id: 'init', role: 'model', text: "Hi! I'm your AI Skincare Assistant. Ask me anything about your skin, ingredients, or routine!" }
  ]);
  const [inputText, setInputText] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [speakingMessageId, setSpeakingMessageId] = useState<string | null>(null);

  const chatSessionRef = useRef<Chat | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const { playClick, playSuccess, announce } = useAccessibility();

  // Initialize chat session
  useEffect(() => {
    try {
        if (!chatSessionRef.current) {
            chatSessionRef.current = createChatSession(userProfile);
        }
    } catch (e) {
        console.error("Failed to init chat", e);
    }
    return () => stopAudio();
  }, [userProfile]);

  const stopAudio = () => {
    if (audioSourceRef.current) {
        audioSourceRef.current.stop();
        audioSourceRef.current = null;
    }
    setSpeakingMessageId(null);
  };

  // Scroll to bottom on new message
  useEffect(() => {
    if (isOpen && messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isOpen]);

  // Focus input when opening
  useEffect(() => {
      if (isOpen) {
          setTimeout(() => {
              inputRef.current?.focus();
          }, 100);
      }
  }, [isOpen]);

  const toggleChat = () => {
      playClick();
      setIsOpen(!isOpen);
      if (!isOpen) {
          announce("Chat opened");
      } else {
          announce("Chat closed");
          stopAudio();
      }
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputText.trim() || isLoading || !chatSessionRef.current) return;

    const userMsg: Message = { id: Date.now().toString(), role: 'user', text: inputText.trim() };
    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setIsLoading(true);
    playClick();

    try {
        const result = await chatSessionRef.current.sendMessage({ message: userMsg.text });
        const aiMsg: Message = {
            id: (Date.now() + 1).toString(),
            role: 'model',
            text: result.text || "I'm sorry, I couldn't understand that."
        };
        setMessages(prev => [...prev, aiMsg]);
        playSuccess();
        announce("New message from AI");
    } catch (err) {
        console.error("Chat Error", err);
        const errorMsg: Message = {
            id: (Date.now() + 1).toString(),
            role: 'model',
            text: "Sorry, I'm having trouble connecting right now. Please try again."
        };
        setMessages(prev => [...prev, errorMsg]);
    } finally {
        setIsLoading(false);
    }
  };

  const speakMessage = async (msg: Message) => {
    if (speakingMessageId === msg.id) {
        stopAudio();
        return;
    }

    stopAudio();
    setSpeakingMessageId(msg.id);
    playClick();

    try {
        const base64Audio = await generateSpeech(msg.text);

        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }

        const ctx = audioContextRef.current;
        if (ctx.state === 'suspended') await ctx.resume();

        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => {
            setSpeakingMessageId(null);
            audioSourceRef.current = null;
        };

        audioSourceRef.current = source;
        source.start();
    } catch (err) {
        console.error("Speech failed", err);
        setSpeakingMessageId(null);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          handleSend();
      }
  };

  return (
    <>
      {/* Floating Action Button */}
      <button
        onClick={toggleChat}
        className={`fixed bottom-6 right-6 z-50 p-4 rounded-full shadow-2xl transition-all duration-300 transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-brand-green/50 ${
            isOpen ? 'bg-gray-200 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rotate-90' : 'bg-brand-green text-white hover:bg-brand-green-dark'
        }`}
        aria-label={isOpen ? "Close Chat" : "Open Skincare Assistant"}
      >
        {isOpen ? <XMarkIcon className="w-6 h-6" /> : <ChatBubbleLeftRightIcon className="w-6 h-6" />}
      </button>

      {/* Chat Window */}
      <div 
        className={`fixed bottom-24 right-6 w-[90vw] sm:w-[380px] bg-white dark:bg-gray-800 rounded-2xl shadow-2xl z-50 flex flex-col overflow-hidden transition-all duration-300 origin-bottom-right border border-gray-100 dark:border-gray-700 ${
            isOpen ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 translate-y-10 pointer-events-none'
        }`}
        style={{ height: 'min(500px, 70vh)' }}
        role="dialog"
        aria-label="AI Skincare Assistant Chat"
      >
        {/* Header */}
        <div className="bg-brand-green p-4 flex items-center justify-between shrink-0">
            <div className="flex items-center text-white">
                <div className="p-1.5 bg-white/20 rounded-lg mr-3">
                    <SparklesIcon className="w-5 h-5" />
                </div>
                <div>
                    <h3 className="font-bold text-sm">Skin Assistant</h3>
                    <p className="text-xs text-brand-green-light opacity-90">Powered by Gemini 3 Pro</p>
                </div>
            </div>
            <button 
                onClick={toggleChat}
                className="text-white/80 hover:text-white transition-colors"
                aria-label="Close"
            >
                <XMarkIcon className="w-5 h-5" />
            </button>
        </div>

        {/* Messages Area */}
        <div className="flex-grow overflow-y-auto p-4 space-y-4 bg-gray-50 dark:bg-gray-900 custom-scrollbar">
            {messages.map((msg) => (
                <div 
                    key={msg.id} 
                    className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}
                >
                    <div 
                        className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm leading-relaxed whitespace-pre-wrap relative group ${
                            msg.role === 'user' 
                            ? 'bg-brand-green text-white rounded-br-none shadow-sm' 
                            : 'bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-bl-none shadow-sm border border-gray-100 dark:border-gray-600'
                        }`}
                    >
                        {msg.text}
                        {msg.role === 'model' && (
                            <button 
                                onClick={() => speakMessage(msg)}
                                className={`absolute -right-8 bottom-0 p-1 rounded-full transition-opacity ${speakingMessageId === msg.id ? 'opacity-100 text-brand-green' : 'opacity-0 group-hover:opacity-100 text-gray-400 hover:text-brand-green'}`}
                                title="Listen"
                            >
                                <AudioSparkIcon className={`w-4 h-4 ${speakingMessageId === msg.id ? 'animate-pulse' : ''}`} />
                            </button>
                        )}
                    </div>
                </div>
            ))}
            {isLoading && (
                <div className="flex justify-start">
                    <div className="bg-white dark:bg-gray-700 rounded-2xl rounded-bl-none px-4 py-3 shadow-sm border border-gray-100 dark:border-gray-600">
                        <div className="flex space-x-1.5">
                            <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                            <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                            <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                        </div>
                    </div>
                </div>
            )}
            <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-3 bg-white dark:bg-gray-800 border-t border-gray-100 dark:border-gray-700 shrink-0">
            <form onSubmit={handleSend} className="relative flex items-end gap-2">
                <textarea
                    ref={inputRef}
                    value={inputText}
                    onChange={(e) => setInputText(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ask about skincare..."
                    className="w-full pl-4 pr-3 py-3 rounded-xl bg-gray-100 dark:bg-gray-700/50 text-gray-900 dark:text-white border-none focus:ring-2 focus:ring-brand-green resize-none text-sm custom-scrollbar max-h-24"
                    rows={1}
                    style={{ minHeight: '44px' }}
                />
                <button
                    type="submit"
                    disabled={!inputText.trim() || isLoading}
                    className="p-3 bg-brand-green text-white rounded-xl hover:bg-brand-green-dark disabled:opacity-50 disabled:cursor-not-allowed transition-colors focus:outline-none focus:ring-2 focus:ring-brand-green mb-[1px]"
                    aria-label="Send message"
                >
                    <PaperAirplaneIcon className="w-5 h-5 -rotate-45 translate-x-[-1px] translate-y-[1px]" />
                </button>
            </form>
            <p className="text-[10px] text-center text-gray-400 mt-2">
                AI can make mistakes. Please verify important info.
            </p>
        </div>
      </div>
    </>
  );
};

