export const analyzeProduct = async (mediaFile: File, userProfile: UserProfile, additionalContext?: string) => {
  if (!process.env.API_KEY) {
    throw new Error("API key is not configured.");
  }
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const mediaPart = await fileToGenerativePart(mediaFile);

  const prompt = `You are a nutritional and dermatological expert. Analyze the product or produce item in the image or video.
  ${additionalContext ? `\nContext from scan: ${additionalContext}` : ''} 

  CRITICAL TASKS:
  1. Identify the product definitively. If it's a produce item (like an apple), determine if it's likely organic vs conventional. If it's a packaged product, find its official ingredient list online.
  2. Use Google Search to find the EXACT ingredient list and check for "Organic" certifications (USDA, COSMOS, etc.).
  3. Determine if the product is 'Highly Processed', 'Minimally Processed', or 'Whole Food'.
  4. Break down ingredients and flag those that are industrial additives (Processed) vs natural/organic.
  5. Based on the user profile, explain potential effects on skin.
  6. Check for any product recalls in the last 12 months.

  User Profile:
  - Skin Type: ${userProfile.skinType}
  - Skin Concerns: ${userProfile.skinConcerns.join(', ')}
  - Health Conditions/Allergies: ${userProfile.healthConditions || 'None specified'}
  - Specific Ingredient Sensitivities: ${
    Object.entries(userProfile.ingredientSensitivities).length > 0
    ? Object.entries(userProfile.ingredientSensitivities)
        .map(([ingredient, level]) => `${ingredient} (${level} sensitivity)`)
        .join(', ')
    : 'None specified'
  }

  Provide your analysis in the specified JSON format.`;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: { parts: [mediaPart, {text: prompt}] },
        config: {
            tools: [{ googleSearch: {} }],
            responseMimeType: 'application/json',
            responseSchema: analysisSchema
        }
    });

    const jsonText = response.text.trim();
    return JSON.parse(jsonText);
  } catch (error) {
    console.error("Error analyzing product:", error);
    throw new Error("Failed to get analysis from the AI. The product might be unclear or the API service is busy.");
  }
};

