        )}

        <div className="text-center px-8">
            <h2 className="text-3xl font-bold text-brand-green-dark dark:text-brand-green truncate mb-3">{result.productName}</h2>
            <div className="flex flex-wrap justify-center gap-2 mb-4">
                <span className={`px-3 py-1 rounded-full text-xs font-bold shadow-sm flex items-center gap-1.5 ${
                    result.organicStatus.toLowerCase().includes('organic') 
                    ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300' 
                    : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400'
                }`}>
                    <LeafIcon className="w-3.5 h-3.5" />
