export const searchProductSelections = async (query: string): Promise<string[]> => {
  if (!process.env.API_KEY) throw new Error("API key is not configured.");
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    // Use Gemini 3 for reliable tool usage with googleSearch
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Perform a Google Search to identify up to 10 distinct, specific, and relevant product names that the user might be looking for when they type "${query}". Focus on precise product titles (e.g., "CeraVe Foaming Facial Cleanser").`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });

    const text = response.text || '';

    try {
        const json = JSON.parse(text);
        if (Array.isArray(json)) {
            return json.slice(0, 10);
        }
        return [];
    } catch (e) {
        console.warn("Failed to parse search selections JSON", e);
        return [];
    }
  } catch (error) {
    console.error("Error searching product selections:", error);
