export const createChatSession = (userProfile: UserProfile, history: Content[] = []): Chat => {
  if (!process.env.API_KEY) throw new Error("API key is not configured.");
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `You are a friendly and expert skincare consultant for the "Skincare Scanner" app.

  Your personality: Professional, encouraging, and deeply knowledgeable.

  Context awareness:
  - ALWAYS refer to the User's Profile provided below for every recommendation.
  - ALWAYS reference previous messages in this conversation to maintain continuity.
  - If the user asks follow-up questions, use the history to provide specific, context-rich answers.

  User Profile:
  - Skin Type: ${userProfile.skinType}
  - Concerns: ${userProfile.skinConcerns.join(', ') || 'None specified'}
  - Health Conditions/Allergies: ${userProfile.healthConditions || 'None specified'}
  - Sensitivities: ${Object.keys(userProfile.ingredientSensitivities).length > 0 ? 
      Object.entries(userProfile.ingredientSensitivities).map(([k, v]) => `${k} (${v} sensitivity)`).join(', ') : 'None specified'}

  Your goal: Help the user understand skincare, ingredients, and products tailored to their specific needs.
  - Warning: Explicitly warn users about products containing ingredients they are sensitive to.
  - Ethical Limit: Do not give medical advice; strongly suggest consulting a licensed dermatologist for persistent or severe skin conditions.`;

  return ai.chats.create({
    model: 'gemini-2.5-flash-lite-latest',
    history: history,
    config: {
      systemInstruction: systemInstruction,
    }
  });
};

/**
 * Text-to-Speech (TTS) feature using gemini-2.5-flash-preview-tts
 */
export const generateSpeech = async (text: string) => {
  if (!process.env.API_KEY) throw new Error("API key is not configured.");
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Say clearly: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) {
      throw new Error("No audio data returned from Gemini TTS.");
    }
    return base64Audio;
  } catch (error) {
    console.error("Error generating speech:", error);
    throw error;
  }
};

/**
 * Audio decoding utilities as per guidelines
 */
export function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Chat, Content } from "@google/genai";
import { UserProfile } from '../types';
